"use client";

/**
 * The Grain Light Card demo: card 0 of a tarot deck, The Fool, with a
 * control panel to try the card's settings.
 *
 * This is the demo that came with the component, almost unchanged. The only
 * difference: the original styled the control panel with Tailwind CSS
 * classes, and this project doesn't use Tailwind (see README.md), so every
 * Tailwind class was swapped for a class in styles.module.css that does the
 * same thing. The card component itself never needed Tailwind.
 */

import * as React from "react";
import { GrainLightCard } from "@/components/ui/grain-light-card";
import styles from "./styles.module.css";

/* ───────── The demo art: tarot card 0, The Fool, and the deck's back ─────────
   Plain line-art SVG. Strokes catch the light; shapes filled with the card stock hide what is behind them.
   The card exposes its colors as CSS variables (--glc-line, --glc-line-strong, --glc-stock-1/2). */

const W = 280, H = 480;
const ART_STYLE =
  ".gf-l{stroke:var(--glc-line)}.gf-ls{stroke:var(--glc-line-strong)}.gf-fill{fill:url(#gf-stock)}" +
  ".gf-s1{stop-color:var(--glc-stock-1)}.gf-s2{stop-color:var(--glc-stock-2)}";
