const f2 = (n: number) => n.toFixed(2);
function starPts(cx: number, cy: number, R: number, r: number, n = 8, rot = -90) {
  const p: string[] = [];
  for (let i = 0; i < n * 2; i++) {
    const a = ((rot + (i * 180) / n) * Math.PI) / 180, rr = i % 2 ? r : R;
    p.push(f2(cx + Math.cos(a) * rr) + "," + f2(cy + Math.sin(a) * rr));
  }
  return p.join(" ");
}
function polarPath(cx: number, cy: number, rFn: (t: number) => number, steps = 360) {
  let d = "";
  for (let i = 0; i <= steps; i++) {
    const t = (i / steps) * Math.PI * 2, r = rFn(t);
    d += (i ? "L" : "M") + f2(cx + Math.cos(t) * r) + " " + f2(cy + Math.sin(t) * r);
  }
  return d + "Z";
}

// Guilloche rosette and a woven border; identical after a 180° turn.
function buildBack() {
  const CX = 140, CY = 240, parts: string[] = [];
  const line = (d: string) => `<path class="gf-l" d="${d}" fill="none" stroke-width="0.4"/>`;
  for (let j = 0; j < 24; j++) { const ph = (j / 24) * Math.PI * 2; parts.push(line(polarPath(CX, CY, t => 52 + 20 * Math.sin(8 * t + ph)))); }
  for (let j = 0; j < 6; j++) { const ph = ((j / 6) * Math.PI * 2) / 32; parts.push(line(polarPath(CX, CY, t => 92 + 5 * Math.sin(32 * t + ph * 32), 720))); }
  for (let j = 0; j < 12; j++) { const ph = (j / 12) * Math.PI * 2; parts.push(line(polarPath(CX, CY, t => 20 + 8 * Math.sin(6 * t + ph)))); }
  [30, 78, 84, 100, 103].forEach((r, i) => {
    const strong = i === 1 || i === 4;
    parts.push(`<circle class="${strong ? "gf-ls" : "gf-l"}" cx="${CX}" cy="${CY}" r="${r}" fill="none" stroke-width="${strong ? 0.8 : 0.5}"/>`);
  });
  parts.push(`<polygon class="gf-ls" points="${starPts(CX, CY, 10, 3.6)}" fill="none" stroke-width="0.9" stroke-linejoin="round"/>`);

  const BI = 26, BR = 14, bx0 = BI, by0 = BI, bx1 = W - BI, by1 = H - BI;
  const sw = bx1 - bx0 - 2 * BR, sh = by1 - by0 - 2 * BR, arc = (Math.PI * BR) / 2;
  type At = (u: number) => [number, number, number, number];
  const corner = (cx: number, cy: number, a0: number): At => u => { const a = a0 + u / BR; return [cx + Math.cos(a) * BR, cy + Math.sin(a) * BR, Math.cos(a), Math.sin(a)]; };
  const segs: { len: number; at: At }[] = [
    { len: sw / 2, at: u => [CX + u, by0, 0, -1] },
    { len: arc, at: corner(bx1 - BR, by0 + BR, -Math.PI / 2) },
    { len: sh, at: u => [bx1, by0 + BR + u, 1, 0] },
    { len: arc, at: corner(bx1 - BR, by1 - BR, 0) },
    { len: sw, at: u => [bx1 - BR - u, by1, 0, 1] },
    { len: arc, at: corner(bx0 + BR, by1 - BR, Math.PI / 2) },
    { len: sh, at: u => [bx0, by1 - BR - u, -1, 0] },
    { len: arc, at: corner(bx0 + BR, by0 + BR, Math.PI) },
    { len: sw / 2, at: u => [bx0 + BR + u, by0, 0, -1] },
  ];
  const L = segs.reduce((a, g) => a + g.len, 0), TW = 2 * Math.round(L / 44 / 2);
  const onPerimeter = (s: number) => { for (const g of segs) { if (s <= g.len) return g.at(s); s -= g.len; } return segs[0].at(0); };
  for (let j = 0; j < 4; j++) {
    let d = "";
    for (let i = 0; i <= 1200; i++) {
      const s = (i / 1200) * L, [x, y, nx, ny] = onPerimeter(s);
      const o = 4 * Math.sin((2 * Math.PI * TW * s) / L + (j * Math.PI) / 2);
      d += (i ? "L" : "M") + f2(x + nx * o) + " " + f2(y + ny * o);
    }
    parts.push(line(d + "Z"));
  }
  const half =
    `<circle class="gf-ls" cx="44" cy="44" r="7" fill="none" stroke-width="0.7"/>` +
    `<polygon class="gf-ls" points="${starPts(44, 44, 5, 1.8)}" fill="none" stroke-width="0.6"/>` +
    `<polygon class="gf-l" points="${starPts(CX, 72, 6, 2.2)}" fill="none" stroke-width="0.6"/>` +
    `<line class="gf-l" x1="${CX}" y1="82" x2="${CX}" y2="${CY - 108}" stroke-width="0.5"/>` +
    `<circle class="gf-ls" cx="${W - 44}" cy="44" r="7" fill="none" stroke-width="0.7"/>` +
    `<polygon class="gf-ls" points="${starPts(W - 44, 44, 5, 1.8)}" fill="none" stroke-width="0.6"/>`;
  parts.push(half, `<g transform="rotate(180 ${W / 2} ${H / 2})">${half}</g>`);
  parts.push(`<rect class="gf-l" x="12" y="12" width="${W - 24}" height="${H - 24}" rx="9" fill="none" stroke-width="0.6"/>`);
  return parts.join("");
}

function Art({ html }: { html: string }) {
  return <svg viewBox={`0 0 ${W} ${H}`} preserveAspectRatio="none" aria-hidden="true" dangerouslySetInnerHTML={{ __html: html }} />;
}

/* ───────── demo controls (same layout as the other demos) ───────── */


function Row({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <div className={styles.row}>
      <span className={styles.rowLabel}>{label}</span>
      {children}
    </div>
  );
}

function Segmented<T extends string>({ label, value, options, onChange }: {
  label: string;
  value: T;
  options: { value: T; label: React.ReactNode }[];
  onChange: (v: T) => void;
}) {
  return (
    <Row label={label}>
      <div role="group" aria-label={label} className={styles.segmented}>
        {options.map(o => (
          <button key={o.value} type="button" aria-pressed={value === o.value} onClick={() => onChange(o.value)} className={styles.segButton}>
            {o.label}
          </button>
        ))}
      </div>
    </Row>
  );
}

function Slider({ label, value, min, max, step, onChange, format = v => v.toFixed(2) }: {
  label: string;
  value: number;
  min: number;
  max: number;
  step: number;
  onChange: (v: number) => void;
  format?: (v: number) => string;
}) {
  return (
    <label className={styles.slider}>
      <span className={styles.sliderLabel}>{label}</span>
      <input type="range" min={min} max={max} step={step} value={value} onChange={e => onChange(parseFloat(e.target.value))} className={styles.sliderInput} />
      <span className={styles.sliderValue}>{format(value)}</span>
    </label>
  );
}

function Group({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <section className={styles.group}>
      <h3 className={styles.groupTitle}>{title}</h3>
      {children}
    </section>
  );
}

export default function GrainLightCardDemo() {
  const [side, setSide] = React.useState<"front" | "back">("front");
  const [theme, setTheme] = React.useState<"light" | "dark">("light");
  const [flash, setFlash] = React.useState(1);
  const [foil, setFoil] = React.useState(0.2);
  const [glare, setGlare] = React.useState(0.6);
  const [sparkle, setSparkle] = React.useState(0.5);
  const [tilt, setTilt] = React.useState(14);
  const [sweep, setSweep] = React.useState(true);
  const [open, setOpen] = React.useState(false);
  const back = React.useMemo(() => `<style>${ART_STYLE}</style>${buildBack()}`, []);
  const dark = theme === "dark";

  return (
    <div className={styles.demo}>
      {/* Stage */}
      <div
        className={styles.stage}
        style={{
          background: dark
            ? "radial-gradient(120% 80% at 50% 38%, #11111a, #07070b 70%)"
            : "radial-gradient(120% 80% at 50% 38%, #dddce3, #c9c8d1 70%)",
        }}
      >
        <GrainLightCard
          label="Tarot card 0, The Fool"
          theme={theme}
          width="min(300px, 72vw, calc((100vh - 200px) * 7 / 12))"
          flipped={side === "back"}
          onFlippedChange={f => setSide(f ? "back" : "front")}
          flash={flash}
          foil={foil}
          glare={glare}
          sparkle={sparkle}
          maxTilt={tilt}
          autoSweep={sweep}
          front={
            <>
              <Art html={`<style>${ART_STYLE}</style>${STOCK}${FOOL}`} />
              <div
                style={{
                  position: "absolute",
                  inset: 0,
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  justifyContent: "space-between",
                  padding: "8.5cqw 9cqw 8cqw",
                  fontFamily: '"Geist", ui-sans-serif, system-ui, sans-serif',
                  fontWeight: 500,
                  pointerEvents: "none",
                }}
              >
                <span style={{ fontSize: "5.6cqw", letterSpacing: ".14em", paddingLeft: ".14em" }}>0</span>
                <span style={{ fontSize: "8cqw", letterSpacing: ".22em", paddingLeft: ".22em", textTransform: "uppercase" }}>The Fool</span>
              </div>
            </>
          }
          back={<Art html={back} />}
        />
      </div>

      {/* Controls */}
      <div className={styles.controls}>
        <div className={styles.controlsHead}>
          <div className={styles.controlsTitle}>
            Grain Light Card <span className={styles.controlsSubtitle}>demo controls</span>
          </div>
          <button
            type="button"
            aria-expanded={open}
            onClick={() => setOpen(v => !v)}
            className={styles.toggleButton}
          >
            {open ? "Hide controls" : "Show controls"}
          </button>
        </div>

        {open && (
          <div className={styles.controlsGrid}>
            <Group title="Preview">
              <Segmented
                label="Side"
                value={side}
                onChange={setSide}
                options={[
                  { value: "front", label: "Front" },
                  { value: "back", label: "Back" },
                ]}
              />
              <Segmented
                label="Theme"
                value={theme}
                onChange={setTheme}
                options={[
                  { value: "light", label: <><span className={styles.swatch} style={{ background: "#dddce3" }} />Light</> },
                  { value: "dark", label: <><span className={styles.swatch} style={{ background: "#11111a" }} />Dark</> },
                ]}
              />
            </Group>

            <Group title="Appearance">
              <Slider label="Flash" value={flash} min={0} max={1} step={0.01} onChange={setFlash} />
              <Slider label="Foil" value={foil} min={0} max={1} step={0.01} onChange={setFoil} />
              <Slider label="Glare" value={glare} min={0} max={1} step={0.01} onChange={setGlare} />
              <Slider label="Sparkle" value={sparkle} min={0} max={1} step={0.01} onChange={setSparkle} />
            </Group>

            <Group title="Motion">
              <Slider label="Tilt" value={tilt} min={0} max={25} step={1} onChange={setTilt} format={v => v + "°"} />
              <label className={styles.checkboxRow}>
                <input type="checkbox" checked={sweep} onChange={e => setSweep(e.target.checked)} className={styles.checkbox} />
                Auto sweep
              </label>
            </Group>
          </div>
        )}
      </div>
    </div>
  );
}
